/* ── Hooks ────────────────────────────────────────── */
function useReveal(threshold) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) { setVisible(true); obs.disconnect(); } },
      { threshold: threshold || 0.1 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}
function Rv({ children, d }) {
  const [ref, vis] = useReveal();
  return (
    <div ref={ref} style={{ opacity: vis ? 1 : 0, transform: vis ? "translateY(0)" : "translateY(28px)", transition: "opacity .7s cubic-bezier(.16,1,.3,1) " + (d || 0) + "s, transform .7s cubic-bezier(.16,1,.3,1) " + (d || 0) + "s" }}>
      {children}
    </div>
  );
}
function useParallax(speed) {
  const ref = useRef(null);
  useEffect(() => {
    const fn = () => { if (ref.current) ref.current.style.transform = "translateY(" + window.scrollY * speed + "px)"; };
    window.addEventListener("scroll", fn, { passive: true });
    return () => window.removeEventListener("scroll", fn);
  }, [speed]);
  return ref;
}

/* ── Pixel Art ────────────────────────────────────── */
function PxCross({ size, color, style: s }) {
  return <svg width={size || 12} height={size || 12} viewBox="0 0 12 12" style={s}><rect x="5" y="0" width="2" height="12" fill={color || "var(--p)"} /><rect x="0" y="5" width="12" height="2" fill={color || "var(--p)"} /></svg>;
}
function PxDiamond({ size, color, style: s }) {
  return <svg width={size || 10} height={size || 10} viewBox="0 0 10 10" style={s}><rect x="4" y="0" width="2" height="2" fill={color || "var(--pl)"} /><rect x="2" y="2" width="2" height="2" fill={color || "var(--pl)"} /><rect x="6" y="2" width="2" height="2" fill={color || "var(--pl)"} /><rect x="0" y="4" width="2" height="2" fill={color || "var(--pl)"} /><rect x="8" y="4" width="2" height="2" fill={color || "var(--pl)"} /><rect x="2" y="6" width="2" height="2" fill={color || "var(--pl)"} /><rect x="6" y="6" width="2" height="2" fill={color || "var(--pl)"} /><rect x="4" y="8" width="2" height="2" fill={color || "var(--pl)"} /></svg>;
}
function PxDot({ size, color, style: s }) {
  return <div style={{ width: size || 6, height: size || 6, background: color || "var(--p)", ...s }} />;
}
function PxGrid({ style: s }) {
  const r = [];
  for (let x = 0; x < 4; x++) for (let y = 0; y < 4; y++) r.push(<rect key={x+"-"+y} x={x*12} y={y*12} width="8" height="8" fill="var(--p)" />);
  return <svg width="48" height="48" viewBox="0 0 48 48" style={{ opacity: 0.08, ...s }}>{r}</svg>;
}

function FloatingPixels() {
  const items = [
    { top: "4%", left: "3%", k: "c", sz: 16, dl: 0 }, { top: "9%", right: "5%", k: "d", sz: 14, dl: 1.4 },
    { top: "16%", left: "7%", k: "g", sz: 48, dl: 0 }, { top: "24%", right: "2%", k: "s", sz: 8, dl: 0.7 },
    { top: "36%", right: "4%", k: "c", sz: 12, dl: 2 }, { top: "44%", left: "5%", k: "d", sz: 16, dl: 0.4 },
    { top: "52%", right: "8%", k: "g", sz: 48, dl: 0 }, { top: "60%", left: "3%", k: "s", sz: 10, dl: 1.8 },
    { top: "70%", left: "6%", k: "c", sz: 14, dl: 1.1 }, { top: "80%", right: "6%", k: "d", sz: 12, dl: 0.5 },
    { top: "88%", left: "4%", k: "g", sz: 48, dl: 0 }, { top: "93%", right: "3%", k: "s", sz: 8, dl: 2.3 },
  ];
  return (
    <div style={{ position: "fixed", inset: 0, pointerEvents: "none", zIndex: 1 }}>
      {items.map((it, i) => {
        const pos = { position: "absolute", top: it.top, left: it.left, right: it.right };
        const anim = { animation: "pxFloat 5s ease-in-out " + it.dl + "s infinite" };
        if (it.k === "c") return <PxCross key={i} size={it.sz} color="var(--pl)" style={{ ...pos, ...anim, opacity: 0.18 }} />;
        if (it.k === "d") return <PxDiamond key={i} size={it.sz} color="var(--pl)" style={{ ...pos, ...anim, opacity: 0.15 }} />;
        if (it.k === "g") return <PxGrid key={i} style={pos} />;
        return <PxDot key={i} size={it.sz} color="var(--pl)" style={{ ...pos, ...anim, opacity: 0.14 }} />;
      })}
    </div>
  );
}

